'use strict';
const menu=document.querySelector('.menu');
menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('#navigation').classList.toggle('open',!expanded);});
const zh=document.documentElement.lang.startsWith('zh');
const stagesZh=[{title:'基线版本 · v0',status:'未检查',delivery:'15 天',freight:'未确认',note:'基线忽略了“工作日”的限定。所有输出都需要质量检查。',state:'warn'},{title:'检查结果 · v0',status:'需要复核',delivery:'15 天 ⚠',freight:'未确认',note:'规则 Q-02：交付时限必须保留原文时间单位。证据 L4 为“15 个工作日”，当前提取不一致。',state:'warn'},{title:'候选版本 · v1',status:'待独立验证',delivery:'15 个工作日 [L4]',freight:'未确认 [L5]',note:'候选变更：保留原始时间单位，缺失信息不得猜测。本示例字段已修正，整体质量与回归表现尚未验证。',state:'good'}];
const stagesEn=[{title:'Baseline · v0',status:'Not checked',delivery:'15 days',freight:'Not confirmed',note:'The baseline missed the qualifier “business”. Every extracted field still needs a quality check.',state:'warn'},{title:'Quality check · v0',status:'Review needed',delivery:'15 days ⚠',freight:'Not confirmed',note:'Rule Q-02: preserve the time unit in the source. Line L4 says “15 business days”; the extraction does not match.',state:'warn'},{title:'Candidate · v1',status:'Awaiting independent testing',delivery:'15 business days [L4]',freight:'Not confirmed [L5]',note:'Proposed change: keep the original time unit and do not guess missing information. This field is corrected; overall quality and regressions have not been tested.',state:'good'}];
const stages=zh?stagesZh:stagesEn;
document.querySelector('[data-language]')?.addEventListener('click',e=>{try{localStorage.setItem('harnessloop-language',e.currentTarget.dataset.language);}catch{}});
function showStage(i){const s=stages[i];const out=document.querySelector('#demo-output');if(!out)return;out.innerHTML=`<div class="demohead"><h3>${s.title}</h3><span class="tag">${s.status}</span></div><div class="result-row"><b>${zh?'数量':'Quantity'}</b><span>${zh?'20 台 [L2]':'20 units [L2]'}</span></div><div class="result-row"><b>${zh?'单价':'Unit price'}</b><span>${zh?'CNY 1,200（含税）[L3]':'CNY 1,200 incl. tax [L3]'}</span></div><div class="result-row"><b>${zh?'交付时限':'Delivery'}</b><span class="${s.state}">${s.delivery}</span></div><div class="result-row"><b>${zh?'运费':'Freight'}</b><span>${s.freight}</span></div><p>${s.note}</p>`;document.querySelectorAll('[data-stage]').forEach((b,index)=>b.setAttribute('aria-selected',String(i===index)));}
document.querySelectorAll('[data-stage]').forEach((b)=>{b.addEventListener('click',()=>showStage(Number(b.dataset.stage)));b.addEventListener('keydown',(e)=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=Number(b.dataset.stage);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;document.querySelector(`[data-stage="${i}"]`).focus();showStage(i);}})});showStage(0);
document.querySelector('#brief-form')?.addEventListener('submit',(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);document.querySelector('#brief').textContent=`${zh?'HarnessLoop 场景简报':'HarnessLoop pilot brief'}\n\n${zh?'业务任务：':'Task: '}${f.get('task')}\n\n${zh?'当前瓶颈：':'Current bottleneck: '}${f.get('pain')}\n\n${zh?'验收标准：':'Acceptance criteria: '}${f.get('criteria')}\n\n${zh?'状态：本地草稿，未发送。':'Status: local draft. Not sent.'}`;document.querySelector('#brief-panel').classList.remove('hidden');document.querySelector('#copy-status').textContent='';});
document.querySelector('#copy-brief')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#brief').textContent);document.querySelector('#copy-status').textContent=zh?'已复制，尚未发送。':'Copied. Not sent.';}catch{document.querySelector('#copy-status').textContent=zh?'无法访问剪贴板，请选中上方简报手动复制。':'Clipboard unavailable. Select the brief above and copy it manually.';}});
